function n8nKey(type){
  const t = String(type||"");
  if (t.startsWith("n8n-nodes-base.")) return t.slice(15);
  if (t.startsWith("@n8n/n8n-nodes-langchain.")) return "@" + t.slice(25);
  return null;
}
/* {glyph, color} si está incrustado, {url, color?} si hay que pedirlo, null si n8n no lo trae */
function n8nIcon(type, dark){
  const k = n8nKey(type), spec = k && N8N_MAP[k];
  if (!spec) return null;
  const [body, colName] = spec.split("#");
  const pal = N8N_COLORS[colName] || N8N_COLORS.black;
  const color = pal[dark ? 1 : 0];
  if (body.startsWith("n:")){
    const g = N8N_GLYPHS[body.slice(2)];
    return g ? {glyph:g, color} : null;
  }
  if (body.startsWith("fa:")) return {url: FA_CDN + body.slice(3) + ".svg", color};
  const [path, darkFile] = body.slice(2).split("|");
  return {url: N8N_CDN[body[0]] + (dark && darkFile ? path.replace(/[^/]+$/, darkFile) : path)};
}

/* logos ya descargados como data: URI, para que el SVG exportado no dependa de nada externo */
const iconCache = new Map(), iconPending = new Map();
const iconKey = ic => ic.url + (ic.color ? "#" + ic.color : "");
const svgDataUri = s => "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(s)));
const blobDataUri = b => new Promise((res, rej)=>{
  const fr = new FileReader();
  fr.onload = ()=>res(fr.result); fr.onerror = rej;
  fr.readAsDataURL(b);
});
function fetchIcon(ic){
  const key = iconKey(ic);
  if (iconCache.has(key)) return Promise.resolve();
  if (iconPending.has(key)) return iconPending.get(key);
  const p = fetch(ic.url)
    .then(r=>{ if (!r.ok) throw new Error(r.status); return /\.png$/i.test(ic.url) ? r.blob() : r.text(); })
    .then(data=>{
      if (typeof data !== "string") return blobDataUri(data);
      /* Font Awesome viene sin color: se le pone el de n8n */
      if (ic.color && !/<svg\b[^>]*\sfill=/.test(data)) data = data.replace(/<svg\b/, `<svg fill="${ic.color}"`);
      return svgDataUri(data);
    })
    .then(uri=>{ iconCache.set(key, uri); }, ()=>{ iconCache.set(key, null); })
    .finally(()=>{ iconPending.delete(key); });
  iconPending.set(key, p);
  return p;
}
/* pide los logos que falten; responde true si llegó alguno nuevo */
async function ensureIcons(model, opts){
  if (!model || opts.icons !== "n8n") return false;
  const dark = isDarkTheme(opts.theme);
  const need = model.nodes.map(n=>n8nIcon(n.type, dark)).filter(ic=>ic && ic.url && !iconCache.has(iconKey(ic)));
  if (!need.length) return false;
  await Promise.all(need.map(fetchIcon));
  return true;
}
const isDarkTheme = t => t === "dark" || t === "blueprint";

