function brandOf(type){
  const t = String(type||"");
  for (const [re,color,mono,icon] of BRANDS) if (re.test(t)) return {color,mono,icon:ICONS[icon]};
  const base = shortType(t);
  return {color:"#6b6878", mono:(base.slice(0,3)||"N8N").toUpperCase()};
}
function shortType(t){
  const parts = String(t||"").split(".");
  return parts[parts.length-1] || "node";
}
const TRIGGER_RE = /trigger$|(?<!respondTo)webhook$|^n8n-nodes-base\.(cron|interval)$/i;
const isTrigger = t => TRIGGER_RE.test(String(t||""));
